steps.step:
browser_evaluate function="() => {
        function lum(r,g,b) {
          const [rs,gs,bs] = [r/255,g/255,b/255].map(c => c<=0.03928 ? c/12.92 : Math.pow((c+0.055)/1.055,2.4));
          return 0.2126*rs + 0.7152*gs + 0.0722*bs;
        }
        function parse(s) { const m=s.match(/(\d+)/g); return m?[+m[0],+m[1],+m[2]]:[0,0,0]; }
        function ratio(fg,bg) { const l1=lum(...fg),l2=lum(...bg); const [a,b]=[Math.max(l1,l2),Math.min(l1,l2)]; return (a+0.05)/(b+0.05); }
        const r=[];
        document.querySelectorAll('h1,h2,h3,h4,h5,h6,p,span,a,button,li,td,th,label,.badge,.card-title').forEach(el=>{
          const s=getComputedStyle(el);
          const cr=ratio(parse(s.color),parse(s.backgroundColor));
          r.push({text:el.textContent.trim().slice(0,30),fg:s.color,bg:s.backgroundColor,ratio:cr.toFixed(2),pass:cr>=4.5});
        });
        return r.filter(x=>!x.pass).slice(0,20);
      }"

browser_fill_form fields=[
        {target: "username-ref", name: "username", type: "textbox", value: "user"},
        {target: "password-ref", name: "password", type: "textbox", value: "pass"}
      ]
